#include <fstream>
using namespace std;

ifstream fin("posta.in");
ofstream fout("posta.out");

long long cmmdc(long long a, long long b) {
    while (b != 0) {
        long long r = a % b;
        a = b;
        b = r;
    }
    return a;
}

int main() {
    int n;
    fin >> n;
    long long g = 0;
    for (int i = 1; i <= n; i++) {
        long long a;
        fin >> a;
        g = cmmdc(g, a - 1);
    }
    fout << g;
    return 0;
}

3002.input:
Fișierul de intrare `cibernetica.in` conține:

• pe prima linie un număr natural $C$, reprezentând tipul ferestrelor de numărat ($1$ sau $2$);
• pe a doua linie două numere naturale $N$ și $K$, reprezentând numărul adreselor IP, și parametrul de siguranță;
• pe a treia linie $N$ numere naturale, reprezentând, în ordinea cererilor, valorile $a_i$ cu semnificația din enunț.

Numerele aflate pe aceeași linie a fișierului sunt separate prin câte un spațiu.

3002.explicatie:
Elementele care apar de cel puțin $2$ ori sunt $1$ și $2$. Deci, ferestrele ce conțin cele două elemente egale cu $1$ sau cu $2$ sunt suspecte. Cele $6$ ferestre suspecte sunt:

• $(1, 2)$ cu adresele IP $[1, 1]$;
• $(1, 3)$ cu adresele IP $[1, 1, 2]$;
• $(1, 4)$ cu adresele IP $[1, 1, 2, 3]$;
• $(1, 5)$ cu adresele IP $[1, 1, 2, 3, 2]$;
• $(2, 5)$ cu adresele IP $[1, 2, 3, 2]$;
• $(3, 5)$ cu adresele IP $[2, 3, 2]$.

