#include <fstream>
using namespace std;

ifstream fin("cibernetica.in");
ofstream fout("cibernetica.out");

const int VMAX = 1000000;
int a[1000005];
int f[VMAX + 1];

int main() {
    int C;
    long long N, K;
    fin >> C >> N >> K;
    for (int i = 1; i <= N; i++) fin >> a[i];
    long long ans = 0;
    long long X = 0;
    int j = 0;
    for (int i = 1; i <= N; i++) {
        while (j < N && !(C == 1 ? X > 0 : X >= K)) {
            j++;
            f[a[j]]++;
            if (C == 1 && f[a[j]] == K) X++;
            if (C == 2 && f[a[j]] == 1) X++;
        }
        if (C == 1 ? X > 0 : X >= K)
            ans += N - j + 1;
        if (C == 1 && f[a[i]] == K) X--;
        if (C == 2 && f[a[i]] == 1) X--;
        f[a[i]]--;
    }
    fout << ans;
    return 0;
}

3003.context:
Collatz are $T$ vectori, fiecare vector $i$ ($1 \le i \le T$) fiind format inițial din numerele naturale consecutive de la $S_i$ la $D_i$. După părerea lui, un vector îngrijit are toate elementele egale cu $1$. Deoarece lui Collatz îi plac vectorii îngrijiți, el își dorește ca toate elementele vectorilor să devină $1$, așa că transformă pe rând vectorii, aplicând pentru fiecare un număr minim de operații. O operație constă din alegerea unui element al vectorului și apoi:

• dacă elementul este **par**, atunci valoarea lui se **înjumătățește**;
• dacă elementul este **impar**, având inițial valoarea $x$, atunci valoarea lui devine $2 \cdot x + 2$.

official_solution.code:
#include <fstream>
using namespace std;

ifstream fin("collatz.in");
ofstream fout("collatz.out");

long long ops(long long x) {
    long long pasi = 0;
    while (x != 1) {
        if (x % 2 == 0) x = x / 2;
        else x = 2 * x + 2;
        pasi++;
    }
    return pasi;
}

long long total(long long st, long long dr, long long m) {
    long long rez = 0;
    while (st <= dr) {
        if (st == 1) st = 2;
        if (st > dr) break;
        if (st % 2 == 0) {
            rez += m * ops(st);
            st++;
        }
        if (st > dr) break;
        if (dr % 2 == 1) {
            rez += m * ops(dr);
            dr--;
        }
        if (st > dr) break;
        long long lung = dr - st + 1;
        rez += m * (lung / 2) * 2;
        rez += m * lung;
        st = (st + 1) / 2;
        dr = dr / 2;
        m = 2 * m;
    }
    return rez;
}

int main() {
    int T;
    fin >> T;
    for (int t = 0; t < T; t++) {
        long long S, D;
        fin >> S >> D;
        fout << total(S, D, 1) << '\n';
    }
    return 0;
}

3004.context:
Se consideră un șir format din $M \cdot N$ termeni a căror valoare poate fi $0$ sau $1$, cele $Q$ poziții în care se găsesc termenii egali cu $1$ fiind $P_1, P_2, \ldots, P_Q$. Termenii șirului sunt memorați, într-o matrice inițială cu $M$ linii și $N$ coloane, astfel încât șirul se obține dacă se parcurge matricea linie cu linie, în ordine, de sus în jos, și fiecare linie de la stânga la dreapta. Pentru un număr $K$ dat, se obține o matrice nouă, cu $M \cdot K$ linii și $N$ coloane, prin scrierea matricei inițiale de $K$ ori, de sus în jos, astfel încât fiecare copie este plasată sub cea de la pasul anterior.

Un grup-1 în matrice este format din una sau mai multe valori $1$ și se consideră că două valori egale cu $1$ fac parte din același grup-1 dacă se poate ajunge de la una la cealaltă parcurgând matricea pe un traseu format doar din elemente egale cu $1$, astfel încât oricare două elemente parcurse consecutiv să fie pe aceeași linie și coloane vecine sau pe aceeași coloană și linii vecine.

De exemplu, dacă $M = 2$, $N = 4$, $Q = 4$, $P_1 = 1$, $P_2 = 3$, $P_3 = 7$, $P_4 = 8$, șirul va avea 8 termeni, $1$, $0$, $1$, $0$, $0$, $0$, $1$, $1$, iar pentru $K$ având valorile $1$, $2$, respectiv $3$, matricele formate sunt:

$$
\begin{pmatrix}
{1} & 0 & {1} & 0 \\
0 & 0 & {1} & {1}
\end{pmatrix}
\quad
\begin{pmatrix}
{1} & 0 & {1} & 0 \\
0 & 0 & {1} & {1} \\
{1} & 0 & {1} & 0 \\
0 & 0 & {1} & {1}
\end{pmatrix}
\quad
\begin{pmatrix}
{1} & 0 & {1} & 0 \\
0 & 0 & {1} & {1} \\
{1} & 0 & {1} & 0 \\
0 & 0 & {1} & {1} \\
{1} & 0 & {1} & 0 \\
0 & 0 & {1} & {1}
\end{pmatrix}
$$

Cele trei matrice au $2$, $3$, respectiv $4$ grupuri-1. Cele $3$ grupuri-1 din a doua matrice sunt formate cu elementele: $\{(1, 1)\}$, $\{(3, 1)\}$, respectiv $\{(1, 3), (2, 3), (2, 4), (3, 3), (4, 3), (4, 4)\}$, elementele din același grup-1 având aceeași culoare.

3004.explicatie:
Pentru primul exemplu termenii egali cu $1$ sunt pe pozițiile $3$ și $5$, deci șirul este $0, 0, 1, 0, 1$, iar matricea formată are o linie și $5$ coloane, conține două grupuri-1 și este:

$$
\begin{pmatrix}
0 & 0 & {1} & 0 & {1}
\end{pmatrix}
$$

