#include <fstream>
#include <algorithm>
#include <vector>
using namespace std;

ifstream fin("unuzero.in");
ofstream fout("unuzero.out");

const int MAXP = 100005;
long long M, N, K;
int Q;
long long P[MAXP];
int grup[MAXP];
int coada[MAXP];

int gaseste(long long p) {
    int i = lower_bound(P, P + Q, p) - P;
    if (i < Q && P[i] == p) return i;
    return -1;
}

int numara() {
    for (int i = 0; i < Q; i++) grup[i] = -1;
    int A = 0;
    for (int s = 0; s < Q; s++) {
        if (grup[s] != -1) continue;
        int prim = 0, ultim = 0;
        coada[ultim++] = s;
        grup[s] = A;
        while (prim < ultim) {
            int x = coada[prim++];
            long long p = P[x], col = (p - 1) % N + 1;
            long long vec[4];
            int nv = 0;
            if (col > 1) vec[nv++] = p - 1;
            if (col < N) vec[nv++] = p + 1;
            if (p > N) vec[nv++] = p - N;
            if (p + N <= M * N) vec[nv++] = p + N;
            for (int d = 0; d < nv; d++) {
                int y = gaseste(vec[d]);
                if (y != -1 && grup[y] == -1) { grup[y] = A; coada[ultim++] = y; }
            }
        }
        A++;
    }
    return A;
}

vector<int> tata;
int sef(int x) {
    while (tata[x] != x) {
        tata[x] = tata[tata[x]];
        x = tata[x];
    }
    return x;
}
bool uneste(int x, int y) {
    x = sef(x); y = sef(y);
    if (x == y) return false;
    tata[x] = y;
    return true;
}

int main() {
    fin >> M >> N >> K >> Q;
    for (int i = 0; i < Q; i++) fin >> P[i];
    int A = numara();
    vector<pair<int, int>> muchii;
    for (int i = 0; i < Q; i++) {
        if (P[i] <= (M - 1) * N) continue;
        long long col = (P[i] - 1) % N + 1;
        int j = gaseste(col);
        if (j != -1) muchii.push_back({grup[i], grup[j]});
    }
    vector<int> cls(A), nou(A), id(2 * A);
    for (int x = 0; x < A; x++) cls[x] = x;
    long long total = A;
    for (long long k = 1; k < K; k++) {
        tata.assign(2 * A, 0);
        for (int x = 0; x < 2 * A; x++) tata[x] = x;
        long long unite = 0;
        for (auto &m : muchii)
            if (uneste(cls[m.first], A + m.second)) unite++;
        total += A - unite;
        for (int x = 0; x < 2 * A; x++) id[x] = -1;
        int cate = 0;
        for (int x = 0; x < A; x++) {
            int r = sef(A + x);
            if (id[r] == -1) id[r] = cate++;
            nou[x] = id[r];
        }
        if (nou == cls) {
            total += (K - 1 - k) * (A - unite);
            break;
        }
        cls = nou;
    }
    fout << total;
    return 0;
}

3005.description:
În clasa lui Ionuț sunt $N$ elevi numerotați cu numere naturale de la $1$ la $N$ așezați în ordinea din catalog. Fiecare elev $i$ ($1 \le i \le N$) are ceea ce se numește un coeficient de popularitate $A_i$, un număr natural nenul. Fiecare elev din clasă are un grup de simpatizanți. Grupul de simpatizanți ai elevului $i$, notat cu $G_i$, este reprezentat de cea mai lungă secvență de elevi din șirul dat în catalog, care îl conține pe elevul $i$, astfel încât coeficientul de popularitate ai fiecărui elev $j$ din secvență, $A_j$, să fie divizor al lui $A_i$. Lungimea secvenței, deci numărul elevilor din grupul de simpatizanți ai lui $i$, se notează cu $|G_i|$. Evident, elevul $i$ face parte din propriul său grup de simpatizanți. Dacă elevul $i$ face parte din grupul de simpatizanți ai elevului $j$, atunci **nu** este neapărat necesar ca și $j$ să facă parte din grupul de simpatizanți al elevului $i$.

După ore, unii elevi își invită la cofetărie grupul de simpatizanți, pentru câte o înghețată. Pentru un grup de simpatizanți $G_i$, elevul $i$ merge și îi cere vânzătoarei exact $|G_i|$ înghețate, dar vânzătoarea are o fire năstrușnică și îi spune că este disponibil doar un anumit număr de arome $k$, mereu cel mult egal cu numărul de înghețate cerute ($1 \le k \le |G_i|$). Elevii, creativi, calculează numărul de moduri în care se poate cumpăra înghețată pentru grup, astfel încât să achiziționeze fiecare sortiment cel puțin o dată; pentru grupul $G_i$, acest număr se notează cu $v_i(k)$.

1. Determinați numărul de ordine din catalog al elevului care are cel mai numeros grup de simpatizanți. Se garantează că există un singur astfel de elev.
2. Lui Ionuț îi place foarte mult să analizeze vânzările magazinelor de înghețată și vă lansează $Q$ întrebări de tipul: $(i, st, dr)$ (cu $1 \le i \le N$ și $1 \le st \le dr \le |G_i|$); pentru fiecare determinați valoarea expresiei: $v_i(st) + v_i(st + 1) + \cdots + v_i(dr)$; cum valoarea poate fi foarte mare, luați în considerare restul împărțirii ei la $10^9 + 7$.

**Explicație**

Pentru al doilea exemplu, $C = 2$, deci se rezolvă a doua cerință. Pentru prima întrebare $G_{10} = \{8, 9, 10\}$ și se calculează $v_{10}(1) + v_{10}(2)$. Dacă vânzătoarea le spune că la magazin se vinde o singură aromă ($k = 1$), atunci este un singur mod de a face cumpărături, anume aceeași aromă pentru toate înghețatele achiziționate. Dacă se vând două arome ($k = 2$), de exemplu ciocolată și vanilie, atunci sunt două posibilități: prima variantă cu una de ciocolată și două de vanilie și a doua variantă cu două de ciocolată și una de vanilie. Deci $v_{10}(1) = 1$, $v_{10}(2) = 2$ și $v_{10}(1) + v_{10}(2) = 3$.

Pentru a doua întrebare $G_4 = \{1, 2, 3, 4, 5\}$. Dacă vânzătoarea le spune că se vând trei arome ($k = 3$), de exemplu ciocolată, vanilie și mentă, sunt $6$ posibilități, deci $v_4(3) = 6$:

1. una de ciocolată, una de vanilie, trei de mentă;
2. una de ciocolată, două de vanilie, două de mentă;
3. una de ciocolată, trei de vanilie, una de mentă;
4. două de ciocolată, una de vanilie, două de mentă;
5. două de ciocolată, două de vanilie, una de mentă;
6. trei de ciocolată, una de vanilie, una de mentă.

3005.cerinta:
