#include <fstream>
#include <vector>
using namespace std;

ifstream fin("inghetata.in");
ofstream fout("inghetata.out");

const long long MOD = 1000000007;
const long long CAP = 1000000001;
int N;
long long A[200005];
int G[200005], L[200005], R[200005];
long long fact[200005], inv[200005];

long long cmmdc(long long a, long long b) {
    while (b) { long long r = a % b; a = b; b = r; }
    return a;
}

long long cmmmc(long long a, long long b) {
    if (a >= CAP || b >= CAP) return CAP;
    long long v = a / cmmdc(a, b) * b;
    return v > CAP ? CAP : v;
}

void stanga(int *capat, int start, int pas) {
    vector<pair<long long, int>> st;
    for (int i = start; i >= 1 && i <= N; i += pas) {
        st.push_back({A[i], i});
        for (auto &e : st) e.first = cmmmc(e.first, A[i]);
        vector<pair<long long, int>> nou;
        for (auto &e : st)
            if (nou.empty() || nou.back().first != e.first) nou.push_back(e);
        st = nou;
        capat[i] = i;
        for (int k = (int)st.size() - 1; k >= 0; k--) {
            if (A[i] % st[k].first != 0) break;
            capat[i] = st[k].second;
        }
    }
}

long long putere(long long b, long long e) {
    long long r = 1;
    b %= MOD;
    while (e > 0) {
        if (e & 1) r = r * b % MOD;
        b = b * b % MOD;
        e >>= 1;
    }
    return r;
}

long long comb(int n, int k) {
    if (k < 0 || k > n) return 0;
    return fact[n] * inv[k] % MOD * inv[n - k] % MOD;
}

int main() {
    int C;
    fin >> C >> N;
    for (int i = 1; i <= N; i++) fin >> A[i];
    stanga(L, 1, +1);
    stanga(R, N, -1);
    for (int i = 1; i <= N; i++) G[i] = R[i] - L[i] + 1;
    if (C == 1) {
        int best = 1;
        for (int i = 2; i <= N; i++) if (G[i] > G[best]) best = i;
        fout << best;
        return 0;
    }
    fact[0] = 1;
    for (int n = 1; n <= N; n++) fact[n] = fact[n - 1] * n % MOD;
    inv[N] = putere(fact[N], MOD - 2);
    for (int n = N; n >= 1; n--) inv[n - 1] = inv[n] * n % MOD;
    int Q;
    fin >> Q;
    for (int q = 0; q < Q; q++) {
        int i, st, dr;
        fin >> i >> st >> dr;
        long long s = 0;
        for (int k = st; k <= dr; k++)
            s = (s + comb(G[i] - 1, k - 1)) % MOD;
        fout << s << '\n';
    }
    return 0;
}

#include <fstream>
