}

#include <fstream>
#include <vector>
using namespace std;

ifstream fin("knight.in");
ofstream fout("knight.out");

const long long MOD = 1000000007;
int N;
int p[200005], fii[200005], adanc[200005];
int nr1[200005];
int tin[200005], tout[200005];
long long prod[200005];
vector<int> copii[200005];

void dfs() {
    vector<pair<int, int>> st;
    int timp = 0;
    st.push_back({1, 0});
    tin[1] = timp++;
    while (!st.empty()) {
        int x = st.back().first;
        int &k = st.back().second;
        if (k < (int)copii[x].size()) {
            int y = copii[x][k++];
            tin[y] = timp++;
            st.push_back({y, 0});
        } else {
            tout[x] = timp++;
            st.pop_back();
        }
    }
}

long long putere(long long b, long long e) {
    long long r = 1;
    b %= MOD;
    while (e > 0) {
        if (e & 1) r = r * b % MOD;
        b = b * b % MOD;
        e >>= 1;
    }
    return r;
}

bool stramos(int x, int y) {
    return tin[x] <= tin[y] && tout[y] <= tout[x];
}

bool accesibil(int a, int b) {
    if (b == 1) return false;
    if (adanc[b] >= adanc[a]) return false;
    if (!stramos(p[b], a)) return false;
    if (stramos(b, a)) return false;
    int pp = p[p[a]];
    return nr1[pp] - nr1[p[b]] == 0;
}

int main() {
    int C;
    fin >> C >> N;
    for (int i = 2; i <= N; i++) {
        fin >> p[i];
        fii[p[i]]++;
        copii[p[i]].push_back(i);
    }
    if (C == 1) {
        int cate = 0;
        for (int x = 1; x <= N; x++) if (fii[x] == 1) cate++;
        fout << cate;
        return 0;
    }
    nr1[1] = (fii[1] == 1);
    prod[1] = (fii[1] >= 2) ? fii[1] - 1 : 1;
    for (int i = 2; i <= N; i++) {
        adanc[i] = adanc[p[i]] + 1;
        nr1[i] = nr1[p[i]] + (fii[i] == 1);
        prod[i] = prod[p[i]] * ((fii[i] >= 2) ? fii[i] - 1 : 1) % MOD;
    }
    dfs();
    int Q;
    fin >> Q;
    for (int q = 0; q < Q; q++) {
        int a, b;
        fin >> a >> b;
        bool ok = accesibil(a, b);
        if (C == 2) { fout << (ok ? 1 : 0) << '\n'; continue; }
        if (!ok) { fout << 0 << '\n'; continue; }
        long long r = prod[p[p[a]]] * putere(prod[p[b]], MOD - 2) % MOD;
        fout << r << '\n';
    }
    return 0;
}

#include <fstream>
#include <string>
using namespace std;

ifstream fin("rotatii.in");
ofstream fout("rotatii.out");

int rez[100005];

long long absl(long long v) { return v < 0 ? -v : v; }

bool accesibil(long long x, long long y, long long pasi) {
    long long d = absl(x) + absl(y);
    return d <= pasi && (pasi - d) % 2 == 0;
}

int main() {
    int C;
    fin >> C;
    if (C == 2) {
        int T;
        fin >> T;
        for (int t = 0; t < T; t++) {
            int N;
            string tr;
            long long a, b;
            fin >> N >> tr >> a >> b;
            fout << (accesibil(a, b, N) ? "DA" : "NU") << '\n';
        }
        return 0;
    }
    int N;
    string tr;
    fin >> N >> tr;
    if (C == 1) {
        long long x = 0, y = 0;
        for (int i = 0; i < N; i++) {
            int rot;
            fin >> rot;
            if (tr[i] == 'N') y++;
            if (tr[i] == 'S') y--;
            if (tr[i] == 'E') x++;
            if (tr[i] == 'V') x--;
            long long nx = x, ny = y;
            if (rot == 90) { nx = y; ny = -x; }
            if (rot == 180) { nx = -x; ny = -y; }
            if (rot == 270) { nx = -y; ny = x; }
            x = nx; y = ny;
        }
        fout << x << ' ' << y;
        return 0;
    }
    long long x, y;
    fin >> x >> y;
    for (int i = N - 1; i >= 0; i--) {
        int rots[4] = {0, 90, 180, 270};
        for (int r : rots) {
            long long qx = x, qy = y;
            if (r == 90) { qx = -y; qy = x; }
            if (r == 180) { qx = -x; qy = -y; }
            if (r == 270) { qx = y; qy = -x; }
            if (tr[i] == 'N') qy--;
            if (tr[i] == 'S') qy++;
            if (tr[i] == 'E') qx--;
            if (tr[i] == 'V') qx++;
            if (accesibil(qx, qy, i)) {
                rez[i] = r;
                x = qx; y = qy;
                break;
            }
        }
    }
    for (int i = 0; i < N; i++) fout << rez[i] << ' ';
    return 0;
}

3009.description:
Se organizează cel mai grandios eveniment în aer liber pentru șoferi: Drive-in cinema cu o parcare imensă matriceală pentru mașini, cu patru ecrane imense la nord, sud, est și vest. Același film este proiectat în toate cele patru direcții. Altfel spus, ai la dispoziție $360^\circ$ de film, deci, oricum ai parca, vei putea viziona filmul fără probleme consumând Tortilla chips cu gust de brânză și Coca-Cola.

Mașinile sosesc în parcare una după alta, având loc și timp suficient să efectueze manevre sigure de parcare. Însă, la finalul evenimentului, toate mașinile vor dori să plece cât mai repede. De aceea, este nevoie de o strategie prin care mașinile să părăsească parcarea în linie dreaptă (fără viraje), păstrând direcția în care erau așezate în timpul filmului, fără să se ciocnească cu alte mașini. Parcarea fiind într-o zonă deschisă, se poate ieși pe oriunde. Altfel spus: tot perimetrul matricei este ieșire. Organizatorii vă roagă să dați o mână de ajutor cu o strategie prin care să eliberați mașinile din parcare una câte una, precizând de fiecare dată coordonatele (linia și coloana) următoarei mașini care pleacă.

Parcarea arată ca o matrice cu $N$ linii și $M$ coloane, pe fiecare loc de parcare fiind câte o mașină parcată către una din direcțiile: Nord (caracterul `^`), Sud (caracterul `v`), Est (caracterul `>`), sau Vest (caracterul `<`). De exemplu, imaginea cu mașinuțele de mai sus reprezintă primul exemplu: $N = 3$ linii și $M = 4$ coloane, iar matricea corespunzătoare se regăsește în imaginea din dreapta.

Aici, o strategie de eliberare este următoarea:

1. Se eliberează mașina de pe $(1, 4)$ — spre Nord, nu are niciun obstacol;
2. Se eliberează mașina de pe $(1, 2)$ — spre Nord, nu are niciun obstacol;
3. Se eliberează mașina de pe $(1, 1)$ — spre Vest, nu are niciun obstacol;
4. Se eliberează mașina de pe $(1, 3)$ — spre Est, mașina din calea ei a plecat deja;
5. Se eliberează mașina de pe $(2, 1)$ — spre Nord, mașina din calea ei a plecat deja;
6. Se eliberează mașina de pe $(2, 3)$ — spre Nord, mașina din calea ei a plecat deja;
7. Se eliberează mașina de pe $(2, 4)$ — spre Est, nu are niciun obstacol;
8. Se eliberează mașina de pe $(2, 2)$ — spre Est, mașinile din calea ei au plecat deja;
9. Se eliberează mașina de pe $(3, 4)$ — spre Sud, nu are niciun obstacol;
10. Se eliberează mașina de pe $(3, 3)$ — spre Est, mașina din calea ei a plecat deja;
11. Se eliberează mașina de pe $(3, 2)$ — spre Sud, nu are niciun obstacol;
12. Se eliberează mașina de pe $(3, 1)$ — spre Est, fiind ultima, are cale liberă.

Cunoscând dimensiunile parcării $N$, $M$ și direcția fiecărei mașini, se cere un plan de eliberare a tuturor mașinilor.

**Explicație**

1. Se eliberează mașina de pe $(1, 2)$ — spre Nord, nu are niciun obstacol;
2. Se eliberează mașina de pe $(2, 2)$ — spre Nord, mașina din calea sa a fost deja eliberată;
3. Se eliberează mașina de pe $(2, 1)$ — spre Vest, nu are niciun obstacol;
4. Se eliberează mașina de pe $(2, 3)$ — spre Vest, mașinile din calea ei au fost deja eliberate;
5. Se eliberează mașina de pe $(1, 3)$ — spre Sud, mașina din calea ei a fost deja eliberată;
6. Se eliberează mașina de pe $(1, 1)$ — spre Est, fiind ultima, are cale liberă.

