#include <fstream>
#include <string>
#include <vector>
using namespace std;

ifstream fin("eliberare.in");
ofstream fout("eliberare.out");
string a[1105];
int N, M;
vector<int> st, dr, sus, jos;
vector<char> plecat;

int blocaj(int x) {
    char d = a[x / M][x % M];
    if (d == '^') return sus[x];
    if (d == 'v') return jos[x];
    if (d == '>') return dr[x];
    return st[x];
}

void scoate(int x) {
    if (st[x] != -1) dr[st[x]] = dr[x];
    if (dr[x] != -1) st[dr[x]] = st[x];
    if (sus[x] != -1) jos[sus[x]] = jos[x];
    if (jos[x] != -1) sus[jos[x]] = sus[x];
    plecat[x] = 1;
    fout << x / M + 1 << ' ' << x % M + 1 << '\n';
}

int main() {
    fin >> N >> M;
    for (int r = 0; r < N; r++) fin >> a[r];
    int T = N * M;
    st.resize(T); dr.resize(T); sus.resize(T); jos.resize(T); plecat.assign(T, 0);
    for (int r = 0; r < N; r++)
        for (int c = 0; c < M; c++) {
            int x = r * M + c;
            st[x] = c > 0 ? x - 1 : -1;
            dr[x] = c < M - 1 ? x + 1 : -1;
            sus[x] = r > 0 ? x - M : -1;
            jos[x] = r < N - 1 ? x + M : -1;
        }
    vector<int> stiva;
    for (int s = 0; s < T; s++) {
        if (plecat[s]) continue;
        stiva.push_back(s);
        while (!stiva.empty()) {
            int x = stiva.back();
            int b = blocaj(x);
            if (b == -1) {
                scoate(x);
                stiva.pop_back();
            } else {
                stiva.push_back(b);
            }
        }
    }
    return 0;
}

