ifstream fin("summat.in");
ofstream fout("summat.out");

long long N;

long long Sum(long long k) {
    long long s = 0, folositi = 0, lung = 1;
    for (long long v = 1; folositi < k; v++, lung *= 2) {
        long long iau = (k - folositi < lung) ? k - folositi : lung;
        s += iau * v;
        folositi += iau;
    }
    return s;
}

long long valoare(long long p) {
    long long v = 0;
    while (p > 0) { p /= 2; v++; }
    return v;
}

long long linie(long long i, long long c1, long long c2) {
    return Sum((i - 1) * N + c2) - Sum((i - 1) * N + c1 - 1);
}

int main() {
    long long M;
    int Q;
    fin >> M >> N >> Q;
    vector<long long> x;
    for (long long start = 1; start <= M * N; start *= 2)
        x.push_back((start - 1) / N + 1);
    for (int q = 0; q < Q; q++) {
        long long l1, c1, l2, c2;
        fin >> l1 >> c1 >> l2 >> c2;
        vector<long long> sp = {l1, l2};
        for (long long r : x)
            if (r >= l1 && r <= l2) sp.push_back(r);
        sort(sp.begin(), sp.end());
        sp.erase(unique(sp.begin(), sp.end()), sp.end());
        long long s = 0;
        for (size_t k = 0; k < sp.size(); k++) {
            s += linie(sp[k], c1, c2);
            if (k + 1 < sp.size() && sp[k + 1] > sp[k] + 1) {
                long long cate = sp[k + 1] - sp[k] - 1;
                long long v = valoare(sp[k] * N + 1);
                s += cate * (c2 - c1 + 1) * v;
            }
        }
        fout << s << '\n';
    }
    return 0;
}

#include <fstream>
