ifstream fin("teleportor.in");
ofstream fout("teleportor.out");

int N, K, P;
int A[1005][1005];
int F[1000005];
int dl[4] = {-1, 1, 0, 0}, dc[4] = {0, 0, -1, 1};

void pereche(int x, int y, int semn) {
    int jos = -1;
    if (y == x + 1) jos = x;
    if (x == y + 1) jos = y;
    if (jos == -1) return;
    if (semn > 0 && F[jos] == 0) P++;
    F[jos] += semn;
    if (semn < 0 && F[jos] == 0) P--;
}

void vecini(int i, int j, int semn) {
    for (int d = 0; d < 4; d++) {
        int a = i + dl[d], b = j + dc[d];
        if (a >= 1 && a <= N && b >= 1 && b <= N) pereche(A[i][j], A[a][b], semn);
    }
}

int main() {
    fin >> N >> K;
    for (int i = 1; i <= N; i++)
        for (int j = 1; j <= N; j++) fin >> A[i][j];
    for (int i = 1; i <= N; i++)
        for (int j = 1; j <= N; j++) {
            if (j < N) pereche(A[i][j], A[i][j + 1], +1);
            if (i < N) pereche(A[i][j], A[i + 1][j], +1);
        }
    fout << K - 1 - P << '\n';
    int Q;
    fin >> Q;
    for (int q = 0; q < Q; q++) {
        int i, j, c;
        fin >> i >> j >> c;
        vecini(i, j, -1);
        A[i][j] = c;
        vecini(i, j, +1);
        fout << K - 1 - P << '\n';
    }
    return 0;
}

