#include <fstream>
#include <iomanip>
#include <algorithm>
using namespace std;

ifstream fin("natatie.in");
ofstream fout("natatie.out");

int N, M;
long long d[3005];
struct Rata { long long v, r; } a[3005];

bool inainte(const Rata &x, const Rata &y) {
    if (x.r != y.r) return x.r < y.r;
    return x.v < y.v;
}

bool poate(double T) {
    int j = 0;
    for (int i = 0; i < N && j < M; i++)
        if (2.0 * d[j] <= T * a[i].v)
            j++;
    return j == M;
}

int main() {
    fin >> N >> M;
    for (int i = 0; i < N; i++) fin >> a[i].v;
    for (int i = 0; i < N; i++) fin >> a[i].r;
    for (int j = 0; j < M; j++) fin >> d[j];
    sort(a, a + N, inainte);
    double st = 0, dr = 2e9;
    for (int pas = 0; pas < 100; pas++) {
        double mij = (st + dr) / 2;
        if (poate(mij)) dr = mij;
        else st = mij;
    }
    fout << fixed << setprecision(6) << dr;
    return 0;
}

#include <fstream>
#include <string>
#include <vector>
using namespace std;

ifstream fin("golf.in");
ofstream fout("golf.out");

int n, m;
vector<string> A;
struct Insula { long long marime; int cmin, cmax, lmin, lmax; };
vector<Insula> ins;
vector<int> coada;

void fill(int i, int j) {
    Insula I = {0, j, j, i, i};
    coada.clear();
    coada.push_back(i * m + j);
    A[i][j] = '2';
    for (size_t k = 0; k < coada.size(); k++) {
        int x = coada[k] / m, y = coada[k] % m;
        I.marime++;
        I.cmin = min(I.cmin, y); I.cmax = max(I.cmax, y);
        I.lmin = min(I.lmin, x); I.lmax = max(I.lmax, x);
        int dx[4] = {-1, 1, 0, 0}, dy[4] = {0, 0, -1, 1};
        for (int d = 0; d < 4; d++) {
            int a = x + dx[d], b = y + dy[d];
            if (a >= 0 && a < n && b >= 0 && b < m && A[a][b] == '1') {
                A[a][b] = '2';
                coada.push_back(a * m + b);
            }
        }
    }
    ins.push_back(I);
}

int main() {
    int T;
    fin >> T >> n >> m;
    A.resize(n);
    long long E = 0;
    for (int i = 0; i < n; i++) {
        fin >> A[i];
        for (char c : A[i]) if (c == '1') E++;
    }
    if (T == 1) { fout << E; return 0; }
    for (int i = 0; i < n; i++)
        for (int j = 0; j < m; j++)
            if (A[i][j] == '1') fill(i, j);
    if (T == 2) {
        long long mx = 0, cate = 0;
        for (auto &I : ins) {
            if (I.marime > mx) { mx = I.marime; cate = 1; }
            else if (I.marime == mx) cate++;
        }
        fout << cate;
        return 0;
    }
    vector<long long> stC(m + 2, 0), drC(m + 2, 0), susL(n + 2, 0), josL(n + 2, 0);
    for (auto &I : ins) {
        stC[I.cmax + 1] += I.marime;
        drC[I.cmin + 1] += I.marime;
        susL[I.lmax + 1] += I.marime;
        josL[I.lmin + 1] += I.marime;
    }
    for (int c = 1; c <= m; c++) stC[c] += stC[c - 1];
    for (int c = m; c >= 1; c--) drC[c] += drC[c + 1];
    for (int l = 1; l <= n; l++) susL[l] += susL[l - 1];
    for (int l = n; l >= 1; l--) josL[l] += josL[l + 1];
    int Q;
    fin >> Q;
    for (int q = 0; q < Q; q++) {
        char t;
        int p;
        fin >> t >> p;
        long long a, b;
        if (t == 'C') { a = stC[p - 1]; b = drC[p + 1]; }
        else { a = susL[p - 1]; b = josL[p + 1]; }
        fout << a * b << '\n';
    }
    return 0;
}

