set<pair<long long, long long>> iv;
long long R;

void taie(long long a, long long b) {
    if (a > b) return;
    auto it = iv.lower_bound({a, -1});
    if (it != iv.begin() && prev(it)->second >= a) --it;
    while (it != iv.end() && it->first <= b) {
        long long l = it->first, r = it->second;
        it = iv.erase(it);
        R -= r - l + 1;
        if (l < a) { iv.insert({l, a - 1}); R += a - l; }
        if (r > b) { iv.insert({b + 1, r}); R += r - b; }
    }
}

