#include <cstdio>

long long tot[100];

bool prim(int x) {
    for (int d = 2; d * d <= x; d++)
        if (x % d == 0) return false;
    return true;
}

int main() {
    FILE *in = fopen("cufere.in", "r"), *out = fopen("cufere.out", "w");
    int c, n;
    fscanf(in, "%d %d", &c, &n);
    for (int k = 0; k < 27 * n; k++) {
        int x;
        fscanf(in, "%d", &x);
        if (x == 0) continue;
        tot[x % 100] += x / 100;
    }
    if (c == 1) {
        for (int e = 10; e <= 99; e++)
            if (tot[e] > 0) fprintf(out, "%d %lld\n", e, tot[e]);
        return 0;
    }
    long long scrise = 0;
    for (int e = 10; e <= 99; e++) {
        int maxim = prim(e) ? 16 : 64;
        long long rest = tot[e];
        while (rest > 0) {
            long long g = rest < maxim ? rest : maxim;
            fprintf(out, "%lld%c", g * 100 + e, (++scrise % 9 == 0) ? '\n' : ' ');
            rest -= g;
        }
    }
    while (scrise < 27LL * n)
        fprintf(out, "0%c", (++scrise % 9 == 0) ? '\n' : ' ');
    return 0;
}

