#include <cstdio>
#include <vector>
using namespace std;

long long fib[50];

signed char cod(long long x) {
    int st = 2, dr = 47;
    while (st < dr) {
        int m = (st + dr) / 2;
        if (fib[m] >= x) dr = m; else st = m + 1;
    }
    if (fib[st] == x) return st;
    int k = (x - fib[st - 1] <= fib[st] - x) ? st - 1 : st;
    return -k;
}

int main() {
    FILE *in = fopen("fibosnek.in", "r"), *out = fopen("fibosnek.out", "w");
    fib[1] = fib[2] = 1;
    for (int k = 3; k < 50; k++) fib[k] = fib[k - 1] + fib[k - 2];
    int c, n, m;
    fscanf(in, "%d %d %d", &c, &n, &m);
    vector<signed char> a((size_t)n * m);
    long long fibo = 0;
    for (int i = 0; i < n; i++)
        for (int j = 0; j < m; j++) {
            long long x;
            fscanf(in, "%lld", &x);
            a[(size_t)j * n + i] = cod(x);
            if (a[(size_t)j * n + i] > 0) fibo++;
        }
    if (c == 1) { fprintf(out, "%lld", fibo); return 0; }
    vector<long long> lung, suma;
    vector<char> tip;
    size_t L = (size_t)n * m;
    for (size_t p = 0; p < L; ) {
        bool f = a[p] > 0;
        long long l = 0, s = 0;
        while (p < L && (a[p] > 0) == f) { l++; s += fib[a[p] > 0 ? a[p] : -a[p]]; p++; }
        lung.push_back(l); suma.push_back(s); tip.push_back(f);
    }
    long long bestL = -1, bestS = 0;
    bool areN = false;
    for (size_t k = 0; k < tip.size(); k++) {
        if (tip[k]) continue;
        areN = true;
        long long l = lung[k], s = suma[k];
        if (k > 0) { l += lung[k - 1]; s += suma[k - 1]; }
        if (k + 1 < tip.size()) { l += lung[k + 1]; s += suma[k + 1]; }
        if (l > bestL) { bestL = l; bestS = s; }
    }
    if (!areN) bestS = suma[0];
    fprintf(out, "%lld", bestS);
    return 0;
}

