long long cmmdc(long long a, long long b) { while (b) { long long r = a % b; a = b; b = r; } return a; }

int main() {
    FILE *in = fopen("arhitect.in", "r"), *out = fopen("arhitect.out", "w");
    int N;
    fscanf(in, "%d", &N);
    vector<pair<long long, long long>> d(N);
    for (int i = 0; i < N; i++) {
        long long x1, y1, x2, y2;
        fscanf(in, "%lld %lld %lld %lld", &x1, &y1, &x2, &y2);
        long long dx = x2 - x1, dy = y2 - y1;
        while (!(dx > 0 && dy >= 0)) { long long t = dx; dx = -dy; dy = t; }
        long long g = cmmdc(dx, dy);
        d[i] = {dx / g, dy / g};
    }
    sort(d.begin(), d.end());
    int best = 0;
    for (int i = 0, j; i < N; i = j) {
        for (j = i; j < N && d[j] == d[i]; j++);
        best = max(best, j - i);
    }
    fprintf(out, "%d", best);
    return 0;
}

#include <fstream>
