ifstream fin("bingo.in");
ofstream fout("bingo.out");

const string W = "bingo";

int rang(char c) { return (int)W.find(c); }

long long cost(const string &s, int *p) {
    long long c = 0;
    for (int k = 0; k < 5; k++) c += abs(p[k] - (p[2] + k - 2));
    for (int a = 0; a < 5; a++)
        for (int b = a + 1; b < 5; b++)
            if (rang(s[p[a]]) > rang(s[p[b]])) c++;
    return c;
}

int main() {
    int T;
    fin >> T;
    for (int t = 0; t < T; t++) {
        string s;
        fin >> s;
        int L = s.size();
        vector<vector<int>> st(5, vector<int>(L, -1)), dr(5, vector<int>(L + 1, -1));
        for (int r = 0; r < 5; r++) {
            int last = -1;
            for (int k = 0; k < L; k++) { st[r][k] = last; if (s[k] == W[r]) last = k; }
            last = -1;
            for (int k = L - 1; k >= 0; k--) { dr[r][k] = last; if (s[k] == W[r]) last = k; }
        }
        int ord[5] = {0, 1, 2, 3, 4};
        long long best = -1;
        do {
            for (int m = 0; m < L; m++) {
                if (s[m] != W[ord[2]]) continue;
                int p[5];
                p[2] = m;
                p[1] = st[ord[1]][p[2]]; if (p[1] < 0) continue;
                p[0] = st[ord[0]][p[1]]; if (p[0] < 0) continue;
                p[3] = dr[ord[3]][p[2]]; if (p[3] < 0) continue;
                p[4] = dr[ord[4]][p[3]]; if (p[4] < 0) continue;
                long long v = cost(s, p);
                if (best < 0 || v < best) best = v;
            }
        } while (next_permutation(ord, ord + 5));
        fout << best << '\n';
    }
    return 0;
}

#include <cstdio>
#include <vector>
#include <algorithm>
#include <queue>
using namespace std;

const long long MOD = 1000000009;
int N, K;
vector<long long> st, dr;
vector<int> f;
vector<long long> fct, inv;
long long putere(long long b, long long e) {
    long long r = 1; b %= MOD;
    while (e > 0) { if (e & 1) r = r * b % MOD; b = b * b % MOD; e >>= 1; }
    return r;
}
long long C(long long n, long long k) { return (k < 0 || k > n) ? 0 : fct[n] * inv[k] % MOD * inv[n - k] % MOD; }

int main() {
    FILE *in = fopen("fotbal.in", "r"), *out = fopen("fotbal.out", "w");
    fscanf(in, "%d %d", &N, &K);
    st.resize(N); dr.resize(N); f.resize(N);
    for (int i = 0; i < N; i++) fscanf(in, "%lld %lld %d", &st[i], &dr[i], &f[i]);
    fct.assign(N + 1, 1); inv.assign(N + 1, 1);
    for (int i = 1; i <= N; i++) fct[i] = fct[i - 1] * i % MOD;
    inv[N] = putere(fct[N], MOD - 2);
    for (int i = N; i >= 1; i--) inv[i - 1] = inv[i] * i % MOD;
    vector<int> ord(N);
    for (int i = 0; i < N; i++) ord[i] = i;
    sort(ord.begin(), ord.end(), [&](int a, int b) { return st[a] < st[b]; });
    priority_queue<pair<long long, int>, vector<pair<long long, int>>, greater<pair<long long, int>>> activ;
    long long cnt[2] = {0, 0};
    long long r = 0;
    for (int i : ord) {
        while (!activ.empty() && activ.top().first < st[i]) {
            cnt[activ.top().second]--;
            activ.pop();
        }
        long long toate = C(cnt[0] + cnt[1], K - 1), aceeasi = C(cnt[f[i]], K - 1);
        r = (r + toate - aceeasi + MOD) % MOD;
        cnt[f[i]]++;
        activ.push({dr[i], f[i]});
    }
    fprintf(out, "%lld", r);
    return 0;
}

#include <cstdio>
