using namespace std;

const long long MOD = 1000000007;
int C, M, N, P, Q, R;

int main() {
    FILE *in = fopen("turcane.in", "r"), *out = fopen("turcane.out", "w");
    fscanf(in, "%d %d %d %d %d %d", &C, &M, &N, &P, &Q, &R);
    if (C == 1) {
        const int INF = 1 << 29;
        vector<vector<int>> d(M + 1, vector<int>(N + 1, INF));
        vector<deque<pair<int, int>>> col(N + 1), dia(M + N + 2);
        for (int i = 1; i <= M; i++) {
            deque<pair<int, int>> lin;
            for (int j = 1; j <= N; j++) {
                auto curata = [](deque<pair<int, int>> &q, int primul) { while (!q.empty() && q.front().first < primul) q.pop_front(); };
                curata(lin, j - P); curata(col[j], i - Q); curata(dia[j - i + M], i - R);
                int best = INF;
                if (i == 1 && j == 1) best = -1;
                if (!lin.empty()) best = min(best, lin.front().second);
                if (!col[j].empty()) best = min(best, col[j].front().second);
                if (!dia[j - i + M].empty()) best = min(best, dia[j - i + M].front().second);
                if (i >= 2 && j >= 3) best = min(best, d[i - 1][j - 2]);
                if (i >= 3 && j >= 2) best = min(best, d[i - 2][j - 1]);
                d[i][j] = (best >= INF) ? INF : best + 1;
                auto pune = [](deque<pair<int, int>> &q, int idx, int v) { while (!q.empty() && q.back().second >= v) q.pop_back(); q.push_back({idx, v}); };
                if (P > 0) pune(lin, j, d[i][j]);
                if (Q > 0) pune(col[j], i, d[i][j]);
                if (R > 0) pune(dia[j - i + M], i, d[i][j]);
            }
        }
        fprintf(out, "%d", d[M][N]);
        return 0;
    }
    vector<vector<long long>> w(M + 1, vector<long long>(N + 1, 0)), L = w, K = w, D = w;
    for (int i = 1; i <= M; i++)
        for (int j = 1; j <= N; j++) {
            long long v = (i == 1 && j == 1) ? 1 : 0;
            if (P > 0) v += L[i][j - 1] - (j - 1 - P >= 1 ? L[i][j - 1 - P] : 0);
            if (Q > 0) v += K[i - 1][j] - (i - 1 - Q >= 1 ? K[i - 1 - Q][j] : 0);
            if (R > 0) v += D[i - 1][j - 1] - (i - 1 - R >= 1 && j - 1 - R >= 1 ? D[i - 1 - R][j - 1 - R] : 0);
            if (i >= 2 && j >= 3) v += w[i - 1][j - 2];
            if (i >= 3 && j >= 2) v += w[i - 2][j - 1];
            w[i][j] = ((v % MOD) + MOD) % MOD;
            L[i][j] = (L[i][j - 1] + w[i][j]) % MOD;
            K[i][j] = (K[i - 1][j] + w[i][j]) % MOD;
            D[i][j] = (D[i - 1][j - 1] + w[i][j]) % MOD;
        }
    fprintf(out, "%lld", w[M][N]);
    return 0;
}

#include <cstdio>
