using namespace std;

int n, m;
vector<vector<int>> ad, inv;

void bfs(const vector<vector<int>> &g, int s, vector<int> &d, vector<int> &par) {
    d.assign(n + 1, -1); par.assign(n + 1, 0);
    vector<int> q = {s};
    d[s] = 0;
    for (size_t h = 0; h < q.size(); h++)
        for (int y : g[q[h]])
            if (d[y] == -1) { d[y] = d[q[h]] + 1; par[y] = q[h]; q.push_back(y); }
}

vector<int> drum(const vector<int> &par, int s, int t) {
    vector<int> p = {t};
    while (t != s) { t = par[t]; p.push_back(t); }
    reverse(p.begin(), p.end());
    return p;
}

void scrie(FILE *out, const vector<int> &p) {
    fprintf(out, "%d\n", (int)p.size() - 1);
    for (size_t k = 0; k < p.size(); k++) fprintf(out, "%d%c", p[k], k + 1 == p.size() ? '\n' : ' ');
}

int main() {
    FILE *in = fopen("veri.in", "r"), *out = fopen("veri.out", "w");
    int c, S, A, B;
    fscanf(in, "%d %d %d %d %d %d", &c, &n, &m, &S, &A, &B);
    ad.assign(n + 1, {}); inv.assign(n + 1, {});
    for (int k = 0; k < m; k++) {
        int x, y;
        fscanf(in, "%d %d", &x, &y);
        ad[x].push_back(y); inv[y].push_back(x);
    }
    vector<int> dS, pS, dA, pA, dB, pB;
    bfs(ad, S, dS, pS);
    bfs(inv, A, dA, pA);
    bfs(inv, B, dB, pB);
    long long best = -1;
    int bi = -1, bu = -1;
    vector<int> d, par;
    for (int i = 1; i <= n; i++) {
        if (dS[i] < 0 || dA[i] < 0 || dB[i] < 0) continue;
        bfs(ad, i, d, par);
        int cyc = -1, u = -1;
        for (int x : inv[i])
            if (d[x] >= 0 && (cyc < 0 || d[x] + 1 < cyc)) { cyc = d[x] + 1; u = x; }
        if (cyc < 0) continue;
        long long v = dS[i] + cyc + max(dA[i], dB[i]);
        if (best < 0 || v < best) { best = v; bi = i; bu = u; }
    }
    if (c == 1) { fprintf(out, "%lld\n", best); return 0; }
    vector<int> p1;
    int Z = -1;
    for (int i = 1; i <= n && Z < 0; i++) {
        if (dS[i] < 0 || dA[i] < 0 || dB[i] < 0) continue;
        bfs(ad, i, d, par);
        int cyc = -1, u = -1;
        for (int x : inv[i]) if (d[x] >= 0 && (cyc < 0 || d[x] + 1 < cyc)) { cyc = d[x] + 1; u = x; }
        if (cyc < 0 || dS[i] + cyc + max(dA[i], dB[i]) != best) continue;
        vector<int> w = drum(pS, S, i), c2 = drum(par, i, u);
        w.insert(w.end(), c2.begin() + 1, c2.end());
        w.push_back(i);
        vector<char> vazut(n + 1, 0);
        size_t k = 0;
        while (!vazut[w[k]]) { vazut[w[k]] = 1; k++; }
        int x = w[k];
        if ((long long)k + max(dA[x], dB[x]) == best) { Z = x; p1.assign(w.begin(), w.begin() + k + 1); }
    }
    vector<int> pa = {Z}, pb = {Z};
    for (int x = Z; x != A; x = pA[x]) pa.push_back(pA[x]);
    for (int x = Z; x != B; x = pB[x]) pb.push_back(pB[x]);
    scrie(out, p1); scrie(out, pa); scrie(out, pb);
    return 0;
}
